/**
 * Fleet registry access layer.
 *
 * The registry is generated by `scripts/seed-fleet.mjs` from Wikidata (CC0) and
 * served from `public/data/fleet-registry.json` rather than bundled, so the
 * vessel catalogue can grow without inflating the app bundle.
 *
 * The query helpers below are pure functions over a registry object, which
 * keeps them testable without any network or bundler involvement.
 */

const REGISTRY_PATH = 'data/fleet-registry.json';

let cachedRegistry = null;
let inFlight = null;

/**
 * Loads (and memoizes) the fleet registry. Resolves relative to Vite's BASE_URL
 * so it works both at the domain root and under a GitHub Pages project subpath.
 * @returns {Promise<object>}
 */
export async function loadFleetRegistry(fetchImpl = globalThis.fetch) {
  if (cachedRegistry) return cachedRegistry;
  if (inFlight) return inFlight;

  const base = import.meta.env?.BASE_URL ?? './';
  const url = `${base.endsWith('/') ? base : `${base}/`}${REGISTRY_PATH}`;

  inFlight = fetchImpl(url)
    .then((response) => {
      if (!response.ok) {
        throw new Error(`Failed to load fleet registry (${response.status})`);
      }
      return response.json();
    })
    .then((registry) => {
      cachedRegistry = registry;
      inFlight = null;
      return registry;
    })
    .catch((error) => {
      inFlight = null;
      throw error;
    });

  return inFlight;
}

/** Test seam: clears the memoized registry. */
export function resetFleetRegistryCache() {
  cachedRegistry = null;
  inFlight = null;
}

/** @returns {object|null} the vessel with this IMO, or null. */
export function findShipByImo(registry, imo) {
  if (!registry?.ships || !imo) return null;
  const target = String(imo).trim();
  return registry.ships.find((ship) => ship.imo === target) ?? null;
}

/** Case-insensitive exact-then-substring name lookup. */
export function findShipByName(registry, name) {
  if (!registry?.ships || !name) return null;
  const needle = name.trim().toLowerCase();
  const ships = registry.ships.filter((s) => s.name);
  return (
    ships.find((s) => s.name.toLowerCase() === needle) ??
    ships.find((s) => s.name.toLowerCase().includes(needle)) ??
    null
  );
}

/**
 * Sister ships: other vessels sharing a hull class. These share the great
 * majority of their deck layout, so a deck plan digitized for one is a strong
 * starting template for the rest.
 * @returns {object[]} classmates excluding the ship itself
 */
export function getSisterShips(registry, imo) {
  const ship = findShipByImo(registry, imo);
  if (!ship?.shipClassId) return [];
  return registry.ships.filter(
    (candidate) => candidate.shipClassId === ship.shipClassId && candidate.imo !== ship.imo
  );
}

/** All vessels operated by a brand (case-insensitive). */
export function getShipsByOperator(registry, operator) {
  if (!registry?.ships || !operator) return [];
  const needle = operator.trim().toLowerCase();
  return registry.ships.filter((s) => s.operator && s.operator.toLowerCase().includes(needle));
}

/**
 * Ship classes ordered by how many vessels they cover — i.e. the highest-value
 * targets for deck-plan digitization, since one plan seeds every sister.
 */
export function getClassesByCoverage(registry, { minShips = 2 } = {}) {
  if (!registry?.classes) return [];
  return registry.classes
    .filter((c) => c.shipCount >= minShips)
    .slice()
    .sort((a, b) => b.shipCount - a.shipCount);
}
